#include <iostream>
#include <iomanip>

int main()
{
    const int value = 42;

    // 1. Default padding (spaces)
    std::cout << "Default spaces:   [" << std::setw(8) << value << "]\n";

    // 2. Member function fill('*') with right justification
    char oldFill = std::cout.fill('*');
    std::cout << "Right with '*':    [" << std::setw(8) << value << "]\n";

    // 3. Manipulator setfill('#') with left justification
    std::cout << "Left with '#':     [" << std::left << std::setw(8) << std::setfill('#') << value << "]\n";

    // 4. Internal justification with showpos and setfill('0')
    std::cout << "Internal with '0': [" << std::internal << std::showpos << std::setw(8) << std::setfill('0') << value << "]\n";

    // Restore default fill and flags
    std::cout.fill(oldFill);
    std::cout << std::right << std::noshowpos;
    return 0;
}

#include <iostream>
#include <iomanip>

int main()
{
    int n = 255;
    std::cout << "Decimal:     " << n << "\n";
    std::cout << std::showbase;
    std::cout << "Octal:       " << std::oct << n << "\n";
    std::cout << "Hex:         " << std::hex << n << "\n";
    std::cout << std::dec << std::noshowbase;

    double pi = 3.1415926535;
    std::cout << "\nDefault float: " << pi << "\n";
    std::cout << "Scientific:    " << std::scientific << std::setprecision(4) << pi << "\n";
    std::cout << "Fixed:         " << std::fixed << std::setprecision(2) << pi << "\n";
    std::cout << std::defaultfloat; // Modern C++ reset
    return 0;
}

#include <iostream>

int main()
{
    // Uppercase demonstration
    std::cout << "Lowercase hex: " << std::hex << std::showbase << 3735928559U << "\n";
    std::cout << "Uppercase hex: " << std::uppercase << 3735928559U << "\n";
    std::cout << "Uppercase exp: " << std::scientific << 1.25e8 << "\n";
    std::cout << std::nouppercase << std::dec << std::noshowbase << std::defaultfloat;

    // Boolalpha demonstration
    bool isActive = true;
    bool hasError = false;
    std::cout << "\nNumeric bool:   " << isActive << ", " << hasError << "\n";
    std::cout << "Boolalpha bool: " << std::boolalpha << isActive << ", " << hasError << "\n";
    std::cout << std::noboolalpha;
    return 0;
}
